<?php require_once __DIR__.'/../includes/layout.php'; require_permission('madrasas.manage'); 
$fields=array (
  'name' => 'Name',
  'district' => 'District',
  'status' => 'Status',
  'sort_order' => 'Sort Order',
); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $id=(int)($_POST['id']??0); if(isset($_POST['delete'])){db()->prepare('DELETE FROM madrasas WHERE id=?')->execute([$id]); audit('delete','madrasas',$id);} else {$cols=array_keys($fields); if($id){$set=implode(',',array_map(fn($c)=>"$c=?",$cols)); $args=array_map(fn($c)=>$_POST[$c]??'',$cols); $args[]=$id; db()->prepare("UPDATE madrasas SET $set WHERE id=?")->execute($args); audit('update','madrasas',$id);} else {$ph=implode(',',array_fill(0,count($cols),'?')); db()->prepare('INSERT INTO madrasas('.implode(',',$cols).') VALUES ('.$ph.')')->execute(array_map(fn($c)=>$_POST[$c]??'',$cols)); audit('create','madrasas',(int)db()->lastInsertId());}}}
$q='%'.($_GET['q']??'').'%'; $rows=db()->prepare('SELECT * FROM madrasas WHERE '.array_key_first($fields).' LIKE ? ORDER BY id DESC LIMIT 200'); $rows->execute([$q]); dashboard_header('Manage Madrasas'); ?><div class="glass-card p-4"><form class="mb-3"><input name="q" class="form-control" placeholder="Search"></form><form method="post" class="row g-2 mb-4"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><?php foreach($fields as $f=>$l):?><div class="col-md"><input name="<?=$f?>" class="form-control" placeholder="<?=$l?>"></div><?php endforeach;?><div class="col-auto"><button class="btn btn-premium">Add</button></div></form><table class="table"><tr><?php foreach($fields as $l):?><th><?=e($l)?></th><?php endforeach;?><th>Actions</th></tr><?php foreach($rows as $r):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><?php foreach($fields as $f=>$l):?><td><input name="<?=$f?>" value="<?=e($r[$f])?>" class="form-control form-control-sm"></td><?php endforeach;?><td><button class="btn btn-sm btn-premium">Edit</button> <button name="delete" value="1" class="btn btn-sm btn-outline-danger" onclick="return confirm('Delete?')">Delete</button></td></form></tr><?php endforeach;?></table></div><?php dashboard_footer(); ?>